export enum AppState {
  UPLOADING = 'UPLOADING',
  CONFIGURING = 'CONFIGURING',
  GENERATING = 'GENERATING',
  VIEWING_QUIZ = 'VIEWING_QUIZ',
  ERROR = 'ERROR',
}

export enum FocusArea {
  VOCABULARY = 'Vocabulary',
  GRAMMAR = 'Grammar',
  READING_COMPREHENSION = 'Reading Comprehension',
  MIXED = 'Mixed',
}

export enum QuizType {
  MULTIPLE_CHOICE = 'Multiple Choice',
  SENTENCE_TRANSFORMATION = 'Sentence Transformation',
}

export interface UploadedFile {
  name: string;
  type: string;
  size: number;
  content: string; // Base64 for images, text content for documents
}

export interface QuizQuestion {
  type: QuizType;
  question: string;
  // Multiple Choice specific
  options?: string[];
  correctAnswerIndex?: number;
  // Sentence Transformation specific
  keyword?: string;
  correctAnswer?: string;
}

export interface QuizConfig {
  numQuestions: number;
  focusArea: FocusArea;
  quizType: QuizType;
}

import { FocusArea, QuizType } from './types';

export const SUPPORTED_FILE_TYPES = [
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'text/plain',
  'application/vnd.ms-powerpoint',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'image/jpeg',
  'image/png',
  'image/jpg',
];

export const FOCUS_AREAS: FocusArea[] = [
  FocusArea.MIXED,
  FocusArea.READING_COMPREHENSION,
  FocusArea.VOCABULARY,
  FocusArea.GRAMMAR,
];

export const QUIZ_TYPES: QuizType[] = [
  QuizType.MULTIPLE_CHOICE,
  QuizType.SENTENCE_TRANSFORMATION,
];

export const QUESTION_COUNTS: number[] = [5, 10, 15];

export const MOCK_EXTRACTED_TEXT = `This is a sample text extracted from your document. QuizMaster AI will use this content to generate your quiz. For documents like PDFs, Word files, and text files, we parse the content directly. For images, we use advanced OCR to recognize and extract the text. You can review and edit this text before proceeding to generate the questions.`;

import React, { useState, useCallback } from 'react';
import { AppState, QuizQuestion, QuizConfig, UploadedFile, FocusArea, QuizType } from './types';
import FileUpload from './components/FileUpload';
import QuizConfigComponent from './components/QuizConfig';
import QuizView from './components/QuizView';
import { generateQuiz } from './services/geminiService';
import Spinner from './components/icons/Spinner';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.UPLOADING);
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [extractedText, setExtractedText] = useState<string>('');
  const [quizConfig, setQuizConfig] = useState<QuizConfig>({
    numQuestions: 5,
    focusArea: FocusArea.MIXED,
    quizType: QuizType.MULTIPLE_CHOICE,
  });
  const [quizData, setQuizData] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);

  const handleFilesUploaded = useCallback((files: UploadedFile[], text: string) => {
    setUploadedFiles(files);
    setExtractedText(text);
    setAppState(AppState.CONFIGURING);
  }, []);

  const handleGenerateQuiz = useCallback(async (config: QuizConfig) => {
    setQuizConfig(config);
    setAppState(AppState.GENERATING);
    setError(null);

    try {
      const imageParts = uploadedFiles
        .filter(file => file.type.startsWith('image/'))
        .map(file => ({
          inlineData: {
            mimeType: file.type,
            data: file.content.split(',')[1],
          },
        }));

      const generatedQuestions = await generateQuiz(
        extractedText,
        imageParts,
        config.numQuestions,
        config.focusArea,
        config.quizType
      );
      setQuizData(generatedQuestions);
      setAppState(AppState.VIEWING_QUIZ);
    } catch (e) {
      console.error(e);
      const errorMessage = e instanceof Error ? e.message : 'An unknown error occurred.';
      setError(`Failed to generate quiz. ${errorMessage}`);
      setAppState(AppState.ERROR);
    }
  }, [uploadedFiles, extractedText]);

  const handleCreateNew = useCallback(() => {
    setUploadedFiles([]);
    setExtractedText('');
    setQuizData([]);
    setError(null);
    setAppState(AppState.UPLOADING);
  }, []);

  const renderContent = () => {
    switch (appState) {
      case AppState.UPLOADING:
        return <FileUpload onFilesUploaded={handleFilesUploaded} />;
      case AppState.CONFIGURING:
        return <QuizConfigComponent extractedText={extractedText} onGenerateQuiz={handleGenerateQuiz} isLoading={false} />;
      case AppState.GENERATING:
        return (
          <div className="text-center p-8">
            <div className="flex justify-center items-center mb-4">
              <Spinner />
            </div>
            <h2 className="text-2xl font-semibold text-slate-700">Generating Your Quiz...</h2>
            <p className="text-slate-500 mt-2">Our AI is hard at work. This might take a moment.</p>
          </div>
        );
      case AppState.VIEWING_QUIZ:
        return <QuizView quizData={quizData} onCreateNew={handleCreateNew} />;
      case AppState.ERROR:
        return (
          <div className="text-center p-8 bg-red-50 border border-red-200 rounded-lg">
            <h2 className="text-2xl font-semibold text-red-700">Oops! Something went wrong.</h2>
            <p className="text-red-600 mt-2 mb-4">{error}</p>
            <button
              onClick={handleCreateNew}
              className="px-6 py-2 bg-red-600 text-white font-semibold rounded-lg hover:bg-red-700 transition-colors"
            >
              Start Over
            </button>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center p-4 sm:p-6 lg:p-8">
      <header className="w-full max-w-5xl mb-8 text-center">
        <h1 className="text-4xl sm:text-5xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-purple-500 to-indigo-600">
          QuizMaster AI
        </h1>
        <p className="mt-2 text-lg text-slate-600">Turn any document or image into a quiz instantly.</p>
      </header>
      <main className="w-full max-w-5xl bg-white rounded-2xl shadow-xl p-4 sm:p-8">
        {renderContent()}
      </main>
      <footer className="mt-8 text-center text-slate-500 text-sm">
        <p>Powered by Gemini API</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { QuizConfig, FocusArea, QuizType } from '../types';
import { FOCUS_AREAS, QUESTION_COUNTS, QUIZ_TYPES } from '../constants';
import Spinner from './icons/Spinner';

interface QuizConfigProps {
  extractedText: string;
  onGenerateQuiz: (config: QuizConfig) => void;
  isLoading: boolean;
}

const QuizConfigComponent: React.FC<QuizConfigProps> = ({ extractedText, onGenerateQuiz, isLoading }) => {
  const [numQuestions, setNumQuestions] = useState<number>(5);
  const [customNumQuestions, setCustomNumQuestions] = useState<string>('');
