  const [quizType, setQuizType] = useState<QuizType>(QuizType.MULTIPLE_CHOICE);
  const [text, setText] = useState(extractedText);

  const finalNumQuestions = numQuestions === -1 ? parseInt(customNumQuestions, 10) : numQuestions;

  const handleSubmit = () => {
    if (isLoading || (numQuestions === -1 && (isNaN(finalNumQuestions) || finalNumQuestions < 1))) return;
    onGenerateQuiz({ numQuestions: finalNumQuestions, focusArea, quizType });
  };

  return (
    <div className="w-full">
      <h2 className="text-2xl font-bold mb-4 text-slate-800">Step 2: Review & Configure</h2>
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div>
          <label htmlFor="extracted-text" className="block text-sm font-medium text-slate-700 mb-2">
            Extracted Content (Editable)
          </label>
          <textarea
            id="extracted-text"
            value={text}
            onChange={(e) => setText(e.target.value)}
            className="w-full h-96 p-3 border border-slate-300 rounded-lg shadow-sm focus:ring-indigo-500 focus:border-indigo-500 transition font-mono text-sm"
            placeholder="Extracted text will appear here..."
          />
        </div>
        <div className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Quiz Type</label>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {QUIZ_TYPES.map(type => (
                <button
                  key={type}
                  onClick={() => setQuizType(type)}
                  className={`px-4 py-3 rounded-lg font-medium text-sm transition-all border ${
                    quizType === type
                      ? 'bg-indigo-50 border-indigo-500 text-indigo-700 ring-1 ring-indigo-500'
                      : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-50'
                  }`}
                >
                  {type}
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Number of Questions</label>
            <div className="flex flex-wrap gap-2">
              {QUESTION_COUNTS.map(count => (
                <button
                  key={count}
                  onClick={() => { setNumQuestions(count); setCustomNumQuestions(''); }}
                  className={`px-4 py-2 rounded-lg font-medium transition-colors ${numQuestions === count ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-700 hover:bg-slate-300'}`}
                >
                  {count}
                </button>
              ))}
              <button
                onClick={() => setNumQuestions(-1)}
                className={`px-4 py-2 rounded-lg font-medium transition-colors ${numQuestions === -1 ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-700 hover:bg-slate-300'}`}
              >
                Custom
              </button>
            </div>
            {numQuestions === -1 && (
              <input
                type="number"
                min="1"
                value={customNumQuestions}
                onChange={(e) => setCustomNumQuestions(e.target.value)}
                className="mt-2 w-full p-2 border border-slate-300 rounded-lg shadow-sm focus:ring-indigo-500 focus:border-indigo-500"
                placeholder="Enter number"
              />
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Focus Area</label>
            <select
              value={focusArea}
              onChange={(e) => setFocusArea(e.target.value as FocusArea)}
              className="w-full p-2 border border-slate-300 rounded-lg shadow-sm focus:ring-indigo-500 focus:border-indigo-500"
            >
              {FOCUS_AREAS.map(area => (
                <option key={area} value={area}>{area}</option>
              ))}
            </select>
          </div>

          <button
            onClick={handleSubmit}
            disabled={isLoading || (numQuestions === -1 && (isNaN(finalNumQuestions) || finalNumQuestions < 1))}
            className="w-full flex justify-center items-center py-3 px-4 bg-indigo-600 text-white font-semibold rounded-lg shadow-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:bg-indigo-300 disabled:cursor-not-allowed transition-all"
          >
            {isLoading ? <Spinner /> : 'Generate Quiz'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default QuizConfigComponent;

import { GoogleGenAI, Type } from "@google/genai";
import { QuizQuestion, FocusArea, QuizType } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

// Schema for Multiple Choice
const multipleChoiceSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      question: {
        type: Type.STRING,
        description: 'The quiz question text, formatted as a "fill-in-the-blank" sentence with "_______".',
      },
      options: {
        type: Type.ARRAY,
        items: { type: Type.STRING },
        description: 'An array of exactly 4 possible answers (A, B, C, D) to fill the blank.',
      },
      correctAnswerIndex: {
        type: Type.INTEGER,
        description: 'The 0-based index of the correct answer in the options array.',
      },
    },
    required: ['question', 'options', 'correctAnswerIndex'],
  },
};

// Schema for Sentence Transformation
const sentenceTransformationSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      question: {
        type: Type.STRING,
        description: 'The original sentence that needs to be transformed.',
      },
      keyword: {
        type: Type.STRING,
        description: 'The keyword given to the user to use in the transformation.',
      },
      correctAnswer: {
        type: Type.STRING,
        description: 'The correct transformed sentence.',
      },
    },
    required: ['question', 'keyword', 'correctAnswer'],
  },
};

export const generateQuiz = async (
  text: string,
  imageParts: { inlineData: { mimeType: string; data: string } }[],
  numQuestions: number,
  focusArea: FocusArea,
  quizType: QuizType
): Promise<QuizQuestion[]> => {
  const model = 'gemini-2.5-flash';

  let systemInstruction = '';
  let focusSpecificInstruction = '';
  let schema: any;

  if (quizType === QuizType.MULTIPLE_CHOICE) {
    schema = multipleChoiceSchema;
    systemInstruction = `You MUST ONLY generate "fill-in-the-blank" style questions. Each question must be a sentence with a single word or short phrase missing, represented by '_______'. Provide exactly 4 multiple-choice options for the blank.`;

    switch (focusArea) {
      case FocusArea.VOCABULARY:
        focusSpecificInstruction = `The blanks should specifically test key vocabulary words from the context.`;
        break;
      case FocusArea.GRAMMAR:
        focusSpecificInstruction = `The blanks and options should create practical grammar exercises, testing concepts like verb tenses, prepositions, or articles based on the context.`;
        break;
      case FocusArea.READING_COMPREHENSION:
        focusSpecificInstruction = `The blanks should test the user's recall of key facts, details, or concepts from the context.`;
        break;
      case FocusArea.MIXED:
      default:
        focusSpecificInstruction = `The questions should be a mix, testing vocabulary, grammar, and key details from the context.`;
        break;
    }

  } else if (quizType === QuizType.SENTENCE_TRANSFORMATION) {
    schema = sentenceTransformationSchema;
    systemInstruction = `You MUST generate "Sentence Transformation" exercises. For each item, provide an original sentence based on the context, a specific 'keyword' (e.g., a conjunction, verb form, preposition), and the correct transformed sentence. The goal is for the user to rewrite the original sentence using the keyword so it has a similar meaning.`;

    switch (focusArea) {
        case FocusArea.VOCABULARY:
          focusSpecificInstruction = `Focus on synonyms, phrasal verbs, and expressions found in the text.`;
          break;
        case FocusArea.GRAMMAR:
          focusSpecificInstruction = `Focus on grammatical structures like passive voice, reported speech, conditionals, or relative clauses relevant to the text style.`;
          break;
        case FocusArea.READING_COMPREHENSION:
        case FocusArea.MIXED:
        default:
          focusSpecificInstruction = `Generate exercises that test understanding of the text's nuance by paraphrasing sentences from the content.`;
          break;
    }
  }

  const promptText = `Based on the following context, please generate a quiz.

**Context:** "${text}"

**Instructions:**
- Type: ${quizType}
- Count: ${numQuestions} questions.
- Focus: ${focusArea}
- ${systemInstruction}
- ${focusSpecificInstruction}
- The output must be a valid JSON array conforming to the schema.

Generate the quiz now.`;

  const textPart = { text: promptText };
  const contents = { parts: [...imageParts, textPart] };

  const response = await ai.models.generateContent({
    model: model,
    contents: contents,
    config: {
      responseMimeType: 'application/json',
      responseSchema: schema,
      temperature: 0.5,
    },
  });

  const jsonResponse = response.text;

  try {
    const parsedData = JSON.parse(jsonResponse);
    if (!Array.isArray(parsedData)) {
      throw new Error("API did not return a valid array.");
    }

    // Normalize data structure
    return parsedData.map((item: any) => ({
      ...item,
      type: quizType, // Explicitly tag the type
      // Ensure defaults for optional fields if schema wasn't perfectly adhered to
      options: item.options || [],
      correctAnswerIndex: item.correctAnswerIndex,
      keyword: item.keyword,
      correctAnswer: item.correctAnswer,
    })) as QuizQuestion[];

  } catch (error) {
    console.error("Failed to parse Gemini response:", jsonResponse);
    throw new Error("Could not understand the AI's response. Please try again.");
  }
};

import React, { useState } from 'react';
import { QuizQuestion, QuizType } from '../types';
import { Document, Packer, Paragraph, TextRun, Numbering, LevelFormat, AlignmentType } from 'docx';

interface QuizViewProps {
  quizData: QuizQuestion[];
  onCreateNew: () => void;
}

const QuizQuestionCard: React.FC<{ question: QuizQuestion; index: number }> = ({ question, index }) => {
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [userTypedAnswer, setUserTypedAnswer] = useState<string>('');
  const [showAnswer, setShowAnswer] = useState(false);
  const [isCorrect, setIsCorrect] = useState<boolean | null>(null);

  const handleSelectAnswer = (optionIndex: number) => {
    if (showAnswer) return;
    setSelectedAnswer(optionIndex);
  };

  const checkTypedAnswer = () => {
    if (!question.correctAnswer) return;
    const normalizedUser = userTypedAnswer.trim().toLowerCase().replace(/[.,!?;]/g, '');
    const normalizedCorrect = question.correctAnswer.trim().toLowerCase().replace(/[.,!?;]/g, '');
    setIsCorrect(normalizedUser === normalizedCorrect);
    setShowAnswer(true);
  };

  const getOptionClass = (optionIndex: number) => {
    if (showAnswer && question.type === QuizType.MULTIPLE_CHOICE) {
      if (optionIndex === question.correctAnswerIndex) {
        return 'bg-green-100 border-green-500 text-green-800';
      }
      if (optionIndex === selectedAnswer) {
        return 'bg-red-100 border-red-500 text-red-800';
      }
    } else {
      if (optionIndex === selectedAnswer) {
        return 'bg-indigo-100 border-indigo-500';
      }
    }
    return 'bg-white hover:bg-slate-50';
  };

  const renderMultipleChoice = () => (
    <div className="space-y-3">
      {question.options?.map((option, i) => (
        <button
          key={i}
          onClick={() => handleSelectAnswer(i)}
          className={`w-full text-left p-3 border rounded-lg transition-all ${getOptionClass(i)}`}
        >
          <span className="font-mono mr-3">{String.fromCharCode(65 + i)}</span>
          {option}
        </button>
      ))}
    </div>
  );

  const renderSentenceTransformation = () => (
    <div className="space-y-4">
      <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 text-slate-700">
        <p className="mb-2 text-sm text-slate-500 uppercase tracking-wider font-semibold">Original Sentence</p>
        <p className="italic">"{question.question}"</p>
      </div>
      <div className="text-center py-2">
        <span className="bg-slate-200 text-slate-800 px-3 py-1 rounded font-bold text-sm tracking-widest uppercase">
          {question.keyword}
        </span>
      </div>
      <div>
         <label className="block text-sm text-slate-600 mb-1">Your Answer:</label>
         <input 
            type="text" 
            className={`w-full p-3 border rounded-lg focus:ring-2 focus:outline-none transition-colors ${
                showAnswer 
                  ? isCorrect 
                    ? 'border-green-500 bg-green-50 focus:ring-green-200' 
                    : 'border-red-300 bg-red-50 focus:ring-red-200'
                  : 'border-slate-300 focus:border-indigo-500 focus:ring-indigo-200'
            }`}
            placeholder="Type the complete transformed sentence..."
            value={userTypedAnswer}
            onChange={(e) => !showAnswer && setUserTypedAnswer(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && !showAnswer && checkTypedAnswer()}
         />
      </div>
      {showAnswer && (
        <div className="mt-4 p-3 bg-green-50 border border-green-200 rounded-lg text-green-800">
            <p className="font-semibold text-sm mb-1">Correct Answer:</p>
            <p>{question.correctAnswer}</p>
        </div>
      )}
    </div>
  );

  return (
    <div className="bg-white p-6 rounded-lg shadow-md border border-slate-200">
      <div className="mb-4">
        <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">{question.type}</span>
        <p className="text-lg font-semibold text-slate-800 mt-1">
            {index + 1}. {question.type === QuizType.SENTENCE_TRANSFORMATION ? "Complete the second sentence so that it has a similar meaning to the first sentence, using the word given." : question.question}
        </p>
      </div>

      {question.type === QuizType.MULTIPLE_CHOICE && renderMultipleChoice()}
      {question.type === QuizType.SENTENCE_TRANSFORMATION && renderSentenceTransformation()}

      <div className="mt-4 text-right">
        {question.type === QuizType.SENTENCE_TRANSFORMATION ? (
             !showAnswer ? (
                <button onClick={checkTypedAnswer} className="px-4 py-2 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-700 transition-colors">
                    Check Answer
                </button>
             ) : (
                <button onClick={() => {setShowAnswer(false); setUserTypedAnswer(''); setIsCorrect(null);}} className="text-sm font-semibold text-slate-500 hover:text-slate-700">
                    Reset
                </button>
             )
        ) : (
             <button onClick={() => setShowAnswer(!showAnswer)} className="text-sm font-semibold text-indigo-600 hover:text-indigo-800">
               {showAnswer ? 'Hide' : 'Show'} Answer
             </button>
        )}
      </div>
    </div>
  );
};

const QuizView: React.FC<QuizViewProps> = ({ quizData, onCreateNew }) => {
  const handleExport = (format: 'json' | 'docx') => {
    if (format === 'json') {
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(quizData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", "quiz.json");
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
    } else if (format === 'docx') {
      generateDocx(quizData);
    }
  };

  const generateDocx = (data: QuizQuestion[]) => {
    const numbering = {
      config: [
        {
          reference: "quiz-numbering",
          levels: [
            {
              level: 0,
              format: LevelFormat.DECIMAL,
              text: "%1.",
              style: { paragraph: { indent: { left: 720, hanging: 360 } } },
            },
            {
              level: 1,
              format: LevelFormat.LOWER_LETTER,
              text: "%2)",
              style: { paragraph: { indent: { left: 1440, hanging: 360 } } },
            },
          ],
        },
      ],
    };

    const docChildren = [
        new Paragraph({ text: "QuizMaster AI Generated Quiz", heading: "Title", alignment: AlignmentType.CENTER }),
        new Paragraph({ text: "" }),
    ];

    data.forEach(q => {
        if (q.type === QuizType.MULTIPLE_CHOICE) {
            docChildren.push(new Paragraph({ text: q.question, numbering: { reference: "quiz-numbering", level: 0 } }));
            q.options?.forEach((opt, i) => {
                docChildren.push(new Paragraph({
                    children: [new TextRun({ text: opt, color: i === q.correctAnswerIndex ? "FF0000" : undefined })],
                    numbering: { reference: "quiz-numbering", level: 1 },
                }));
            });
        } else if (q.type === QuizType.SENTENCE_TRANSFORMATION) {
             docChildren.push(new Paragraph({ 
                 text: "Complete the sentence using the word: " + q.keyword, 
                 numbering: { reference: "quiz-numbering", level: 0 },
                 heading: "Heading3"
            }));
             docChildren.push(new Paragraph({ text: "Original: " + q.question }));
             docChildren.push(new Paragraph({ text: "Keyword: " + q.keyword, bold: true }));
             docChildren.push(new Paragraph({ text: "Answer: ___________________________" }));
             docChildren.push(new Paragraph({ 
                 children: [new TextRun({ text: "Correct Answer: " + q.correctAnswer, color: "FF0000" })],
             }));
        }
        docChildren.push(new Paragraph({ text: "" }));
    });

    const doc = new Document({
      numbering,
      sections: [{ children: docChildren }],
    });

    Packer.toBlob(doc).then(blob => {
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "quiz.docx";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    });
