import { GoogleGenAI, Type } from "@google/genai";
import { QuizQuestion, FocusArea } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

const quizSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      question: {
        type: Type.STRING,
        description: 'The quiz question text, formatted as a "fill-in-the-blank" sentence with "_______".',
      },
      options: {
        type: Type.ARRAY,
        items: { type: Type.STRING },
        description: 'An array of exactly 4 possible answers (A, B, C, D) to fill the blank.',
      },
      correctAnswerIndex: {
        type: Type.INTEGER,
        description: 'The 0-based index of the correct answer in the options array.',
      },
    },
    required: ['question', 'options', 'correctAnswerIndex'],
  },
};

export const generateQuiz = async (
  text: string,
  imageParts: { inlineData: { mimeType: string; data: string } }[],
  numQuestions: number,
  focusArea: FocusArea
): Promise<QuizQuestion[]> => {
  const model = 'gemini-2.5-flash';

  const baseInstruction = `You MUST ONLY generate "fill-in-the-blank" style questions that are practical application exercises. DO NOT generate questions that ask for definitions or theoretical concepts. Each question must be a sentence with a single word or short phrase missing, represented by '_______'. Provide exactly 4 multiple-choice options for the blank. The sentences and options must be derived from the provided context. If the context provided is short (e.g. just a topic name), use your general knowledge about that topic to generate the questions.`;

  let focusSpecificInstruction = '';
  switch (focusArea) {
    case FocusArea.VOCABULARY:
      focusSpecificInstruction = `The blanks should specifically test key vocabulary words associated with the context or topic.`;
      break;
    case FocusArea.GRAMMAR:
      focusSpecificInstruction = `The blanks and options should create practical grammar exercises, testing concepts like verb tenses, prepositions, or articles relevant to the context. DO NOT ask for definitions of grammar terms; instead, create sentences where the user must apply the correct grammatical form.`;
      break;
    case FocusArea.READING_COMPREHENSION:
      focusSpecificInstruction = `The blanks should test the user's recall of key facts, details, or concepts from the context. If only a topic is provided, test general knowledge about that topic.`;
      break;
    case FocusArea.MIXED:
    default:
      focusSpecificInstruction = `The questions should be a mix, testing vocabulary, grammar, and key details.`;
      break;
  }

  const textPart = {
    text: `Based on the following context, please generate a multiple-choice quiz.

**CRITICAL INSTRUCTIONS:**
${baseInstruction}
${focusSpecificInstruction}

For example: "The doctor decided to _______ the patient's throat to check for infection." with options like ["suffer", "treat", "strengthen", "examine"].

Context: "${text}"

Quiz Requirements:
- Number of questions: ${numQuestions}
- Format: Every single question MUST be "fill-in-the-blank" with 4 options.
- Only one option can be correct.
- The output must be a valid JSON array of objects, conforming to the provided schema.

Generate the quiz now.`
  };

  const contents = {
    parts: [...imageParts, textPart]
  };

  const response = await ai.models.generateContent({
    model: model,
    contents: contents,
    config: {
      responseMimeType: 'application/json',
      responseSchema: quizSchema,
      temperature: 0.5,
    },
  });

  const jsonResponse = response.text;

  try {
    const quizData = JSON.parse(jsonResponse);
    // Basic validation
    if (!Array.isArray(quizData)) {
      throw new Error("API did not return a valid array.");
    }
    quizData.forEach(item => {
        if (!item.question || !Array.isArray(item.options) || typeof item.correctAnswerIndex !== 'number' || item.options.length !== 4) {
            throw new Error('API returned malformed quiz data.');
        }
    });
    return quizData as QuizQuestion[];
  } catch (error) {
    console.error("Failed to parse Gemini response:", jsonResponse);
    throw new Error("Could not understand the AI's response. Please try again.");
  }
};

