const QuizView: React.FC<QuizViewProps> = ({ quizData, onCreateNew }) => {
  const [copyStatus, setCopyStatus] = useState<'idle' | 'copied'>('idle');

  const handleExport = (format: 'json' | 'docx') => {
    if (format === 'json') {
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(quizData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", "quiz.json");
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
    } else if (format === 'docx') {
      generateDocx(quizData);
    }
  };

  const handleCopyText = async () => {
    if (!navigator.clipboard) return;

    // Create HTML version (Rich Text) for Word/Docs/Email
    let html = `<html><body><h2 style="color: #334155;">QuizMaster AI Generated Quiz</h2>`;
    quizData.forEach((q, idx) => {
      html += `<div style="margin-bottom: 24px;">`;
      html += `<p style="font-size: 16px; font-weight: bold; margin-bottom: 8px;">${idx + 1}. ${q.question}</p>`;
      html += `<ul style="list-style-type: none; padding-left: 0; margin-top: 0;">`;
      q.options.forEach((opt, optIdx) => {
        const isCorrect = optIdx === q.correctAnswerIndex;
        // Correct answer in RED
        const style = isCorrect ? 'color: #dc2626; font-weight: bold;' : 'color: #334155;';
        html += `<li style="${style} padding: 4px 0;">${String.fromCharCode(65 + optIdx)}) ${opt}</li>`;
      });
      html += `</ul></div>`;
    });
    html += `</body></html>`;

    // Create Plain Text version (Fallback)
    let text = `QuizMaster AI Generated Quiz\n\n`;
    quizData.forEach((q, idx) => {
      text += `${idx + 1}. ${q.question}\n`;
      q.options.forEach((opt, optIdx) => {
        const isCorrect = optIdx === q.correctAnswerIndex;
        const marker = isCorrect ? ' [CORRECT]' : '';
        text += `${String.fromCharCode(65 + optIdx)}) ${opt}${marker}\n`;
      });
      text += `\n`;
    });

    try {
      // @ts-ignore - ClipboardItem is a global but TS might not be aware in all configs
      const item = new ClipboardItem({
        'text/html': new Blob([html], { type: 'text/html' }),
        'text/plain': new Blob([text], { type: 'text/plain' }),
      });
      await navigator.clipboard.write([item]);
      setCopyStatus('copied');
      setTimeout(() => setCopyStatus('idle'), 2000);
    } catch (err) {
      console.error('Failed to copy', err);
      // Fallback to text only if rich copy fails
      try {
        await navigator.clipboard.writeText(text);
        setCopyStatus('copied');
        setTimeout(() => setCopyStatus('idle'), 2000);
      } catch (e) {
        console.error('Fallback copy failed', e);
      }
    }
  };

  const generateDocx = (data: QuizQuestion[]) => {
    const numbering = {
      config: [
        {
          reference: "quiz-numbering",
          levels: [
            {
              level: 0,
              format: LevelFormat.DECIMAL,
              text: "%1.",
              style: { paragraph: { indent: { left: 720, hanging: 360 } } },
            },
            {
              level: 1,
              format: LevelFormat.LOWER_LETTER,
              text: "%2)",
              style: { paragraph: { indent: { left: 1440, hanging: 360 } } },
            },
          ],
        },
      ],
    };

    const doc = new Document({
      numbering,
      sections: [{
        children: [
          new Paragraph({ text: "QuizMaster AI Generated Quiz", heading: "Title", alignment: AlignmentType.CENTER }),
          new Paragraph({ text: "" }),
          ...data.flatMap((q, qi) => [
            new Paragraph({ text: q.question, numbering: { reference: "quiz-numbering", level: 0 } }),
            ...q.options.map((opt, i) => 
              new Paragraph({
                children: [
                  new TextRun({
                    text: opt,
                    color: i === q.correctAnswerIndex ? "FF0000" : undefined,
                  }),
                ],
                numbering: { reference: "quiz-numbering", level: 1 },
              })
            ),
            new Paragraph({ text: "" }),
          ]),
        ],
      }],
    });

    Packer.toBlob(doc).then(blob => {
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "quiz.docx";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    });
  };

  return (
    <div className="w-full">
      <div className="flex flex-col sm:flex-row justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Your Generated Quiz</h2>
        <div className="flex items-center space-x-2 mt-4 sm:mt-0">
          <button 
            onClick={handleCopyText} 
            className={`px-4 py-2 font-semibold rounded-lg transition-colors ${
              copyStatus === 'copied' 
                ? 'bg-green-600 text-white' 
                : 'bg-slate-200 text-slate-700 hover:bg-slate-300'
            }`}
          >
            {copyStatus === 'copied' ? 'Copied!' : 'Copy Text'}
          </button>
          <button onClick={() => handleExport('json')} className="px-4 py-2 bg-slate-200 text-slate-700 font-semibold rounded-lg hover:bg-slate-300 transition-colors">Export JSON</button>
          <button onClick={() => handleExport('docx')} className="px-4 py-2 bg-slate-200 text-slate-700 font-semibold rounded-lg hover:bg-slate-300 transition-colors">Export DOCX</button>
          <button onClick={onCreateNew} className="px-4 py-2 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-700 transition-colors">Create New</button>
        </div>
      </div>
      <div className="space-y-6">
        {quizData.map((q, i) => (
          <QuizQuestionCard key={i} question={q} index={i} />
        ))}
      </div>
    </div>
  );
};

